21	@Injectable({ providedIn: 'root' })
22	export class LectureResolve implements Resolve<Lecture> {
23	    constructor(private lectureService: LectureService) {}
24	
25	    resolve(route: ActivatedRouteSnapshot): Observable<Lecture> {
26	        const lectureId = route.params['lectureId'];
27	        if (lectureId) {
28	            return this.lectureService.find(lectureId).pipe(
29	                filter((response: HttpResponse<Lecture>) => response.ok),
30	                map((lecture: HttpResponse<Lecture>) => lecture.body!),
31	            );
32	        }
33	        return of(new Lecture());
34	    }
35	}
36	
37	@Injectable({ providedIn: 'root' })
38	export class AttachmentResolve implements Resolve<Attachment> {
39	    constructor(private attachmentService: AttachmentService) {}
40	
41	    resolve(route: ActivatedRouteSnapshot): Observable<Attachment> {
42	        const attachmentId = route.params['attachmentId'];
43	        if (attachmentId) {
44	            return this.attachmentService.find(attachmentId).pipe(
45	                filter((response: HttpResponse<Attachment>) => response.ok),
46	                map((attachment: HttpResponse<Attachment>) => attachment.body!),
47	            );
48	        }
49	        return of(new Attachment());
50	    }
51	}
