/**
 * Route guard that warns the user with a confirmation dialog when they try to leave the lecture edit page
 * while there are unsaved changes to the lecture's title, description, channel name or time period.
 *
 * @param component the {@link LectureUpdateComponent} that is being left
 * @param currentRoute the current route snapshot
 * @param currentState the current router state snapshot
 * @param nextState the router state snapshot the user is navigating to
 * @return true if the navigation is allowed, otherwise an Observable emitting the result of the confirmation dialog
 */
export const hasLectureUnsavedChangesGuard = (
    component: LectureUpdateComponent,
    currentRoute: ActivatedRouteSnapshot,
    currentState: RouterStateSnapshot,
    nextState: RouterStateSnapshot,
): MaybeAsync<GuardResult> => {
    // The warning is not active (e.g. right after a successful save), so navigation is always allowed.
    if (!component.shouldDisplayDismissWarning) {
        return true;
    }

    // No relevant changes were made, so navigation is always allowed.
    if (!component.isChangeMadeToTitleOrPeriodSection) {
        return true;
    }

    // There are unsaved changes, so we ask the user whether they really want to leave the page.
    const modalRef = inject(NgbModal).open(CloseEditLectureModalComponent, { size: 'lg', backdrop: 'static' });
    return from(modalRef.result) as Observable<boolean>;
};
